module.script:
"use strict";
/******************************宏代码说明******************************
* 类型：ClientSide
* 对象：鼠标提示带图例对比柱图
* 事件：onBeforeRender
* 效果描述：鼠标移入提示，显示图例数据
**********************************************************************/
function main(page, portlet) {
    var config = {
        type: ['ECHARTS_CONTRAST']
    };
    var type = portlet.getType();
    if (config.type.indexOf(type) < 0)
        return;
    var rows = [];
    // 获取Tooltip数据
    portlet.getTooltipHandler(function (row, column, rowIndex) {
        var obj = {
            'rowValues': row.getValues(),
            'rowFields': row.getFields()
        };
        var ridx = Number(rowIndex);
        if (rows[ridx]) {
            var tmpValue = [];
            var tmpField = [];
            var rowValues = row.getValues();
            var rowFields = row.getFields();
            for (var i in rowValues) {
                var rowValue = rowValues[i];
                var rowField = rowFields[i];
                var flag = true;
                for (var j in rows[ridx]['rowValues']) {
                    if (rowValue && rows[ridx]['rowValues'][j] && rowValue.id === rows[ridx]['rowValues'][j].id) {
                        flag = false;
                        break;
                    }
                }
                if (flag) {
                    tmpValue.push(rowValue);
                    tmpField.push(rowField);
                }
            }
            rows[ridx]['rowValues'] = rows[ridx]['rowValues'].concat(tmpValue);
            rows[ridx]['rowFields'] = rows[ridx]['rowFields'].concat(tmpField);
        }
        else {
            rows[ridx] = obj;
        }
    });
    // 自定义Tooltip信息
    setTooltipInfo(portlet, { rows: rows });
}
/**
 * 设置Tooltip数据
 * 场景：给每一个tooltip提示信息添加数据占比
 */
function setTooltipInfo(portlet, data) {
    var result = []; // 提示信息
    data.rows.forEach(function (el) {
        var rowData = el['rowValues'];
        var fieldData = el['rowFields'];
        var buf = [];
        // 构造原来的Tooltip数据信息
        rowData.forEach(function (em, edx) {
            if (fieldData[edx]) {
                buf.push(fieldData[edx].alias + ":" + em.value + "<br>");
            }
        });
        result.push(buf.join(''));
    });
    // 覆写ECharts中tooltip.formatter格式化信息
    var options = portlet.getChartOptions();
    options.tooltip.formatter = function (params) {
        var tmp = result[params.dataIndex].split('<br>');
        var tooltip = '';
        for (var i in tmp) {
            if (tmp[i] === '')
                continue;
            tooltip += params.marker + tmp[i] + '<br>';
        }
        return tooltip;
    };
    portlet.setChartOptions(options);
}

module.typescript:
/******************************宏代码说明******************************
* 类型：ClientSide
* 对象：鼠标提示带图例对比柱图
* 事件：onBeforeRender
* 效果描述：鼠标移入提示，显示图例数据
**********************************************************************/
function main(page: IPage, portlet: IEChartsPortlet) {
    let config = {
        type: ['ECHARTS_CONTRAST']
    }
    let type = portlet.getType();
    if (config.type.indexOf(type) < 0) return;
    let rows: any = [];
    // 获取Tooltip数据
    portlet.getTooltipHandler((row: ITooltipRow, column: ITooltipColumn, rowIndex: number) => {
        let obj = {
            'rowValues': row.getValues(),
            'rowFields': row.getFields()
        }
        let ridx: number = Number(rowIndex)
        if (rows[ridx]) {
            let tmpValue = []
            let tmpField = []
            let rowValues = row.getValues()
            let rowFields = row.getFields()
            for (let i in rowValues) {
                let rowValue = rowValues[i]
                let rowField = rowFields[i]
                let flag = true
                for (let j in rows[ridx]['rowValues']) {
                    if (rowValue && rows[ridx]['rowValues'][j] && rowValue.id === rows[ridx]['rowValues'][j].id) {
                        flag = false
                        break
                    }
                }
                if (flag) {
                    tmpValue.push(rowValue)
                    tmpField.push(rowField)
                }
            }
            rows[ridx]['rowValues'] = rows[ridx]['rowValues'].concat(tmpValue)
            rows[ridx]['rowFields'] = rows[ridx]['rowFields'].concat(tmpField)
        } else {
            rows[ridx] = obj
        }
    })
    // 自定义Tooltip信息
    setTooltipInfo(portlet, { rows })
}

/**
 * 设置Tooltip数据
 * 场景：给每一个tooltip提示信息添加数据占比
 */
function setTooltipInfo(portlet: IEChartsPortlet, data: any) {
    let result: any = [] // 提示信息
    data.rows.forEach((el: any) => {
        let rowData = el['rowValues']
        let fieldData = el['rowFields']
        let buf:any = []
        // 构造原来的Tooltip数据信息
        rowData.forEach((em: any, edx: number) => {
            if (fieldData[edx]) {
                buf.push(`${fieldData[edx].alias}:${em.value}<br>`)
            }
        })
        result.push(buf.join(''))
    })
    // 覆写ECharts中tooltip.formatter格式化信息
    let options = portlet.getChartOptions()
    options.tooltip.formatter = (params: any) => {
        let tmp = result[params.dataIndex].split('<br>')
        let tooltip = ''
        for (let i in tmp) {
            if (tmp[i] === '') continue
            tooltip += params.marker + tmp[i] + '<br>'
        }
        return tooltip
    }
    portlet.setChartOptions(options)
}

module.script:
"use strict";
/******************************宏代码说明******************************
* 类型：ClientSide
* 对象：环形图
* 事件：onBeforeRender
* 效果描述：南丁格尔图
**********************************************************************/
var __spreadArrays = (this && this.__spreadArrays) || function () {
    for (var s = 0, i = 0, il = arguments.length; i < il; i++) s += arguments[i].length;
    for (var r = Array(s), k = 0, i = 0; i < il; i++)
        for (var a = arguments[i], j = 0, jl = a.length; j < jl; j++, k++)
            r[k] = a[j];
    return r;
};
function main(page, portlet) {
    var config = {
        type: ['ECHARTS_PIE__DONUT', 'ECHARTS_PIE']
    };
    var type = portlet.getType();
    if (config.type.indexOf(type) < 0)
        return;
    /***********开始配置***********/
    var labelConfig = {
        //是否设置数据标签为百分比，若不需要，可将该值修改为false，开启则为true
        isLabelPrecent: true
    };
    /***********结束配置***********/
    clearInterval(SmartbiXMacro.data[portlet.getId() + "南丁格尔图"]);
    SmartbiXMacro.data[portlet.getId() + "南丁格尔图"] = setInterval(function () {
        var options = portlet.getChartOptions();
        if (!options || !options.series || !options.series[0] || !options.series[0].data || !options.series[0].data.length) {
            return;
        }
        clearInterval(SmartbiXMacro.data[portlet.getId() + "南丁格尔图"]);
        //设置外圈图层
        setOuterSerie(options);
        setBaseSerie(options, labelConfig);
        portlet.setChartOptions(options);
    }, 10);
}
/**
 * 设置外圈图层
 */
function setOuterSerie(options) {
    var innerRadius, outerRadius;
    if (options.series[0].radius) {
        innerRadius = options.series[0].radius[1];
        outerRadius = parseFloat(innerRadius.substr(0, innerRadius.indexOf('%'))) + 25 + "%";
    }
    else {
        innerRadius = '75%';
        outerRadius = '100%';
    }
    var serie = JSON.parse(JSON.stringify(options.series[0]));
    serie.radius = [innerRadius, outerRadius];
    serie.zlevel = -2;
    serie.label = {
        normal: {
            position: 'inside',
        }
    };
    for (var i = 0; i < serie.data.length; i++) {
        serie.data[i].value[0] = 1;
        ;
        serie.data[i].label = serie.data[i].label || {};
        serie.data[i].label.formatter = "{b}";
        serie.data[i].label.itemStyle = serie.data[i].label.itemStyle || {};
        serie.data[i].label.color = "#fff";
        serie.data[i].itemStyle = serie.data[i].itemStyle || {};
        serie.data[i].itemStyle.color = options.color[i % options.color.length];
    }
    options.series.push(serie);
}
/**
 * 设置基础图层
 */
function setBaseSerie(options, labelConfig) {
    var serie = options.series[0];
    var color = options.color;
    var borderColor = __spreadArrays(color);
    var opacity = 0.5;
    //饼图的颜色转至透明
    for (var i = 0; i < color.length; i++) {
        if (color[i].indexOf("#") != -1) {
            color[i] = hexToInt(color[i], opacity);
        }
        else {
            var split = color[i].replace(/(?:\(|\)|[a-z]|[A-Z])*/g, "").split(",");
            if (split.length < 3) {
                return;
            }
            else {
                color[i] = "rgba(" + split[0] + "," + split[1] + "," + split[2] + "," + opacity + ")";
            }
        }
    }
    serie.label = serie.label || {};
    var data = serie.data;
    for (var i = 0; i < data.length; i++) {
        data[i].itemStyle = data[i].itemStyle || {};
        data[i].itemStyle.borderColor = borderColor[i % borderColor.length];
        data[i].itemStyle.color = color[i % 10];
        data[i].itemStyle.borderWidth = 2;
        //发光效果
        // data[i].itemStyle.shadowColor = borderColor[i %  borderColor.length];
        // data[i].itemStyle.shadowBlur = 20;
        data[i].label = data[i].label || {};
        data[i].label.formatter = labelConfig.isLabelPrecent ? '{d}%\n{b}' : '{c}\n{b}';
        data[i].label.color = borderColor[i % 10];
        data[i].labelLine = data[i].label || {};
        data[i].labelLine.lineStyle = data[i].labelLine.lineStyle || {};
        data[i].labelLine.lineStyle.color = borderColor[i % borderColor.length];
    }
}
/**
 * 16进制颜色转10进制rgba
 */
function hexToInt(color, opacity) {
    var a = parseInt(color.substring(1, 3), 16);
    var b = parseInt(color.substring(3, 5), 16);
    var c = parseInt(color.substring(5, 7), 16);
    var targetColor = "rgba(" + a + "," + b + "," + c + "," + opacity + ")";
    return targetColor;
}

module.typescript:
/******************************宏代码说明******************************
* 类型：ClientSide
* 对象：环形图
* 事件：onBeforeRender
* 效果描述：南丁格尔图
**********************************************************************/

/**
 * 标签的相关配置
 *  isLabelPrecent: 是否设置数据标签为百分比，若不需要，可将该值修改为false，开启则为true
 */
type LabelConfig = {
    isLabelPrecent: boolean
}
function main(page: IPage, portlet: IEChartsPortlet) {
    let config = {
        type: ['ECHARTS_PIE__DONUT', 'ECHARTS_PIE']
    }
    let type = portlet.getType();
    if (config.type.indexOf(type) < 0) return;
    /***********开始配置***********/
    let labelConfig: LabelConfig = {
        //是否设置数据标签为百分比，若不需要，可将该值修改为false，开启则为true
        isLabelPrecent: true
    }
    /***********结束配置***********/
    clearInterval(SmartbiXMacro.data[portlet.getId() + "南丁格尔图"]);
    SmartbiXMacro.data[portlet.getId() + "南丁格尔图"] = setInterval(function () {
        let options = portlet.getChartOptions();
        if (!options || !options.series || !options.series[0] || !options.series[0].data || !options.series[0].data.length) {
            return;
        }

        clearInterval(SmartbiXMacro.data[portlet.getId() + "南丁格尔图"]);
        //设置外圈图层
        setOuterSerie(options);
        setBaseSerie(options, labelConfig);
        portlet.setChartOptions(options);
    }, 10);
}
/**
 * 设置外圈图层
 */
function setOuterSerie(options: any) {
    let innerRadius, outerRadius;
    if (options.series[0].radius) {
        innerRadius = options.series[0].radius[1];
        outerRadius = parseFloat(innerRadius.substr(0, innerRadius.indexOf('%'))) + 25 + "%";
    } else {
        innerRadius = '75%';
        outerRadius = '100%';
    }
    let serie = JSON.parse(JSON.stringify(options.series[0]));
    serie.radius = [innerRadius, outerRadius];
    serie.zlevel = -2;
    serie.label = {
        normal: {
            position: 'inside',
        }
    };
    for (let i = 0; i < serie.data.length; i++) {
        serie.data[i].value[0] = 1;;
        serie.data[i].label = serie.data[i].label || {};
        serie.data[i].label.formatter = "{b}";
        serie.data[i].label.itemStyle = serie.data[i].label.itemStyle || {};
        serie.data[i].label.color = "#fff";
        serie.data[i].itemStyle = serie.data[i].itemStyle || {};
        serie.data[i].itemStyle.color = options.color[i % options.color.length];
    }
    options.series.push(serie);
}
/**
 * 设置基础图层
 */
function setBaseSerie(options: any, labelConfig:LabelConfig) {
    let serie = options.series[0];
    let color = options.color;
    let borderColor = [...color];
    let opacity = 0.5;
    //饼图的颜色转至透明
    for (let i = 0; i < color.length; i++) {
        if (color[i].indexOf("#") != -1) {
            color[i] = hexToInt(color[i], opacity);
        } else {
            let split = color[i].replace(/(?:\(|\)|[a-z]|[A-Z])*/g, "").split(",");
            if (split.length < 3) {
                return;
            } else {
                color[i] = "rgba(" + split[0] + "," + split[1] + "," + split[2] + "," + opacity + ")";
            }
        }
    }
    serie.label = serie.label || {};
    let data = serie.data;
    for (let i = 0; i < data.length; i++) {
        data[i].itemStyle = data[i].itemStyle || {};
        data[i].itemStyle.borderColor = borderColor[i % borderColor.length];
        data[i].itemStyle.color = color[i % 10];
        data[i].itemStyle.borderWidth = 2;
        //发光效果
        // data[i].itemStyle.shadowColor = borderColor[i %  borderColor.length];
        // data[i].itemStyle.shadowBlur = 20;
        data[i].label = data[i].label || {};
        data[i].label.formatter = labelConfig.isLabelPrecent ? '{d}%\n{b}' : '{c}\n{b}';
        data[i].label.color = borderColor[i % 10];
        data[i].labelLine = data[i].label || {};
        data[i].labelLine.lineStyle = data[i].labelLine.lineStyle || {};
        data[i].labelLine.lineStyle.color = borderColor[i %  borderColor.length];
    }
}
/**
 * 16进制颜色转10进制rgba
 */
function hexToInt(color: any, opacity: any) {
    let a = parseInt(color.substring(1, 3), 16);
    let b = parseInt(color.substring(3, 5), 16);
    let c = parseInt(color.substring(5, 7), 16);
    let targetColor = "rgba(" + a + "," + b + "," + c + "," + opacity + ")";
    return targetColor;
}

module.script:
"use strict";
/******************************宏代码说明******************************

 * 类型：ClientSide

 * 事件：onBeforeRender

 * 效果描述：通过坐标划分为四象限

 * 实现步骤：
 * 1.求x,y轴的最大值
 * 2.给options.xAxis和 options.yAxis设置最大值和最小值

 * （1）判断是否为散点图

 *********************************************************************/
function main(page, portlet) {
    /***************开始配置 *************/
    /*y轴名字的位置*/
    var yNameLocation = "center";
    /***************结束配置 *************/
    //判断是否是为散点图
    var config = {
        type: ['ECHARTS_SCATTER', 'ECHARTS_SCATTER__LARGE']
    };
    var type = portlet.getType();
    if (config.type.indexOf(type) < 0)
        return;
    var options = portlet.getChartOptions();
    //求x,y轴值的最大值
    var max = function (indx) {
        var arry = [];
        for (var _i = 0, _a = options.series[0].data; _i < _a.length; _i++) {
            var item = _a[_i];
            arry.push(Math.ceil(item.value[indx]));
        }
        return Math.max.apply(null, arry);
    };
    //求x,y轴值的最小值
    var min = function (indx) {
        var arry = [];
        for (var _i = 0, _a = options.series[0].data; _i < _a.length; _i++) {
            var item = _a[_i];
            arry.push(Math.ceil(item.value[indx]));
        }
        return Math.min.apply(null, arry);
    };
    //x轴值的最大值
    var xMax = max(0);
    //x轴值的最小值
    var xMin = min(0);
    //y轴值的最大值
    var yMax = max(1);
    //y轴值的最小值
    var yMin = min(1);
    //x轴配置
    var xAxisSetting = options.xAxis;
    if (options.xAxis.type != 'category') {
        xAxisSetting.min = xMin >= 0 ? -xMax : xMin;
        xAxisSetting.max = xMax;
        xAxisSetting.type = 'value';
    }
    options.xAxis = xAxisSetting;
    //y轴配置y
    var yAxisSetting = options.yAxis;
    if (options.yAxis.type != 'category') {
        yAxisSetting.min = yMin >= 0 ? -yMax : yMin;
        yAxisSetting.max = yMax;
        yAxisSetting.nameLocation = yNameLocation;
        options.yAxis = yAxisSetting;
    }
    portlet.setChartOptions(options);
}

module.typescript:
/******************************宏代码说明******************************

 * 类型：ClientSide

 * 事件：onBeforeRender

 * 效果描述：通过坐标划分为四象限

 * 实现步骤：
 * 1.求x,y轴的最大值
 * 2.给options.xAxis和 options.yAxis设置最大值和最小值

 * （1）判断是否为散点图

 *********************************************************************/
function main(page: IPage, portlet: IEChartsPortlet) {
    /***************开始配置 *************/
    /*y轴名字的位置*/
    const yNameLocation = "center";
    /***************结束配置 *************/


    //判断是否是为散点图
    let config = {
        type: ['ECHARTS_SCATTER', 'ECHARTS_SCATTER__LARGE']
    }
    let type = portlet.getType();
    if (config.type.indexOf(type) < 0) return;

    let options = portlet.getChartOptions();

    //求x,y轴值的最大值
    const max = (indx: number) => {
        let arry: any = [];
        for (let item of options.series[0].data) {
            arry.push(Math.ceil(item.value[indx]))
        }
        return Math.max.apply(null, arry);
    }

    //求x,y轴值的最小值
    const min = (indx: number) => {
        let arry: any = [];
        for (let item of options.series[0].data) {
            arry.push(Math.ceil(item.value[indx]))
        }
        return Math.min.apply(null, arry);
    }

    //x轴值的最大值
    let xMax: number = max(0);
    //x轴值的最小值
    let xMin: number = min(0);
    //y轴值的最大值
    let yMax: number = max(1);
    //y轴值的最小值
    let yMin: number = min(1);
    //x轴配置

    let xAxisSetting = options.xAxis
    if (options.xAxis.type != 'category') {
        xAxisSetting.min = xMin >= 0 ? -xMax : xMin
        xAxisSetting.max = xMax
        xAxisSetting.type = 'value'
    }
    options.xAxis = xAxisSetting

    //y轴配置y
    let yAxisSetting = options.yAxis
    if (options.yAxis.type != 'category') {
        yAxisSetting.min = yMin >= 0 ? -yMax : yMin
        yAxisSetting.max = yMax
        yAxisSetting.nameLocation = yNameLocation
        options.yAxis = yAxisSetting
    }
    portlet.setChartOptions(options)
}

module.script:
"use strict";
function main(page, portlet) {
    var config = {
        type: ['ECHARTS_PIE__DONUT', 'ECHARTS_PIE']
    };
    var type = portlet.getType();
    if (config.type.indexOf(type) < 0)
        return;
    /***********开始配置***********/
    var labelConfig = {
        //是否设置数据标签为百分比，若不需要，可将该值修改为false，开启则为true
        isLabelPrecent: true,
        normalLabelColor: '#ffffff',
        emphasisInnerLabelColor: '#333333',
        emphasisInnerItemColor: 'rgb(27, 255, 246)',
        emphasisOuterLabelColor: 'rgb(25, 255, 224)',
        emphasisOuterItemColor: 'rgba(25, 255, 224, 0.2)'
    };
    /***********结束配置***********/
    clearInterval(SmartbiXMacro.data[portlet.getId() + "旋转标签-占比比例-选中效果"]);
    SmartbiXMacro.data[portlet.getId() + "旋转标签-占比比例-选中效果"] = setInterval(function () {
        var options = portlet.getChartOptions();
        if (!options || !options.series || !options.series[0] || !options.series[0].data || !options.series[0].data.length) {
            return;
        }
        clearInterval(SmartbiXMacro.data[portlet.getId() + "旋转标签-占比比例-选中效果"]);
        //设置外圈的标签以及旋转
        setOuterSerie(options, labelConfig);
        //增加透明背景
        setBackgroundSerie(options, labelConfig);
        //设置被选中的颜色
        setEmphasis(portlet, labelConfig);
        portlet.setChartOptions(options);
    }, 10);
}
/**
 * 设置外圈的标签以及旋转
 */
function setOuterSerie(options, labelConfig) {
    var serie = options.series[0];
    var outerSerie = {
        type: 'pie',
        radius: ['85%', '100%'],
        hoverAnimation: false,
        itemStyle: {
            color: 'transparent',
            borderColor: 'transparent'
        },
        labelLine: {
            normal: {
                show: false,
                length: 30,
                length2: 55,
            },
        },
        label: {
            color: '',
            normal: {
                position: 'inside',
                align: 'right',
            },
        },
        tooltip: {
            show: false
        },
        name: '',
        data: SmartbiXMacro.utils.deepClone(true, [], serie.data),
    };
    var total = 0;
    for (var i = 0; i < serie.data.length; i++) {
        total += parseFloat(serie.data[i].value[0]);
    }
    for (var i = 0; i < outerSerie.data.length; i++) {
        //设置标签颜色
        serie.data[i].label = serie.data[i].label || {};
        serie.data[i].label.color = labelConfig.normalLabelColor || serie.label.color;
        outerSerie.data[i]['label'] = outerSerie.data[i]['label'] || {};
        outerSerie.data[i]['label'].color = labelConfig.normalLabelColor || serie.label.color;
        // //设置外部、内部标签的旋转角度
        outerSerie.data[i].value[0] = 1;
        outerSerie.data[i]['label']['rotate'] = angleText(i, outerSerie.data.length);
        serie.data[i]['label']['rotate'] = angleText(i, outerSerie.data.length);
        // //设置外部标签的半径
        outerSerie.radius = outerSerie.radius || ['85%', '100%'];
        var radius0 = '85', radius1 = '100';
        if (serie.radius) {
            radius0 = serie.radius[0].substr(0, serie.radius[0].length - 1);
            radius1 = serie.radius[1].substr(0, serie.radius[1].length - 1);
        }
        var radiusSize = Math.max(parseFloat(radius0), parseFloat(radius1));
        outerSerie.radius[0] = radiusSize + '%';
        outerSerie.radius[1] = radiusSize + 15 + '%';
        // //设置外部、内部标签的显示内容
        var before = labelConfig.isLabelPrecent ? '{d}%' : '{c}';
        serie.data[i].label = serie.data[i].label || {};
        serie.data[i].label.formatter = "" + before;
        outerSerie.data[i].label = outerSerie.data[i].label || {};
        outerSerie.data[i].label.formatter = outerSerie.data[i].displayValue[0];
    }
    options.series.push(outerSerie);
}
/**
 *  增加透明背景
 */
function setBackgroundSerie(option, labelConfig) {
    var serie = option.series[1];
    var bgserie = {
        type: 'pie',
        zlevel: 99,
        //透明背景的半径
        radius: ['15%', '90%'],
        selectedOffset: 0,
        animation: false,
        hoverAnimation: false,
        label: {
            normal: {
                show: false,
            },
        },
        data: SmartbiXMacro.utils.deepClone(true, [], serie.data)
    };
    // //设置背景图的默认颜色,初始时下表为0的图呈现选中状态
    for (var i = 0; i < bgserie.data.length; i++) {
        bgserie.data[i].itemStyle = bgserie.data[i].itemStyle || {};
        bgserie.data[i].itemStyle.borderColor = 'transparent';
        if (i == 0) {
            option.series[0].data[0].label = option.series[0].data[0].label || {};
            option.series[0].data[0].label.color = labelConfig.emphasisInnerLabelColor;
            option.series[0].data[0].itemStyle = option.series[0].data[0].itemStyle || {};
            option.series[0].data[0].itemStyle.color = labelConfig.emphasisInnerItemColor;
            option.series[1].data[0].label = option.series[1].data[0].label || {};
            option.series[1].data[0].label.color = labelConfig.emphasisOuterLabelColor;
            bgserie.data[0].itemStyle.color = labelConfig.emphasisOuterItemColor;
        }
        else {
            bgserie.data[i].itemStyle.color = 'transparent';
        }
    }
    option.series.push(bgserie);
}
/**
 * 设置被选中的颜色
 */
function setEmphasis(portlet, labelConfig) {
    portlet.addChartsListener('click', function (e) {
        var option = portlet.getChartOptions();
        //最外层的字体颜色重置变色
        for (var da1 = 0; da1 < option.series[1].data.length; da1++) {
            option.series[1].data[da1].label = option.series[1].data[da1].label || {};
            option.series[1].data[da1].label.color = labelConfig.normalLabelColor || option.series[0].label.color;
            option.series[1].data[da1].itemStyle = option.series[1].data[da1].itemStyle || {};
        }
        //色圈的字体颜色和选中颜色重置
        for (var da2 = 0; da2 < option.series[0].data.length; da2++) {
            option.series[0].data[da2].itemStyle = option.series[0].data[da2].itemStyle || {};
            delete option.series[0].data[da2].itemStyle;
            option.series[0].data[da2].label = option.series[0].data[da2].label || {};
            delete option.series[0].data[da2].label.color;
        }
        // //背景的透明饼图的重置
        for (var da3 = 0; da3 < option.series[2].data.length; da3++) {
            option.series[2].data[da3].itemStyle = option.series[2].data[da3].itemStyle || {};
            option.series[2].data[da3].itemStyle.color = 'transparent';
        }
        //hover 颜色改变
        option.series[0].data[e.dataIndex].label = option.series[0].data[e.dataIndex].label || {};
        option.series[0].data[e.dataIndex].label.color = labelConfig.emphasisInnerLabelColor;
        option.series[0].data[e.dataIndex].itemStyle = option.series[0].data[e.dataIndex].itemStyle || {};
        option.series[0].data[e.dataIndex].itemStyle.color = labelConfig.emphasisInnerItemColor;
        option.series[1].data[e.dataIndex].label = option.series[1].data[e.dataIndex].label || {};
        option.series[1].data[e.dataIndex].label.color = labelConfig.emphasisOuterLabelColor;
        option.series[2].data[e.dataIndex].itemStyle = option.series[2].data[e.dataIndex].itemStyle || {};
        option.series[2].data[e.dataIndex].itemStyle.color = labelConfig.emphasisOuterItemColor;
        portlet.setChartOptions(option);
    });
}
/**
 * 旋转标签
 */
function angleText(i, num) {
    //每个元素的角度
    var everyAngle = 360 / num;
    //文字现在所在的角度
    var currentAngle = i * everyAngle + everyAngle / 2;
    //文字所在模块的所占角度
    var currentArea = (i + 1) * everyAngle;
    if (currentAngle <= 90) {
        return -currentAngle;
    }
    else if (currentAngle <= 180 && currentAngle > 90) {
        return 180 - currentAngle;
    }
    else if (currentAngle < 270 && currentAngle > 180) {
        return 180 - currentAngle;
    }
    else if (currentAngle < 360 && currentAngle >= 270) {
        return 360 - currentAngle;
    }
}

