/**
 * 效果：旋转标签-占比比例-选中效果
 * 类型：ClientSide
 * 对象：不规则环形图-标签在内
 * 事件：onBeforeRender
 */
/**
 * 标签的相关配置
 *  isLabelPrecent: 是否设置数据标签为百分比，若不需要，可将该值修改为false，开启则为true
 *  normalLabelColor: 默认文字颜色
 *  emphasisInnerLabelColor: 高亮数据块扇形内圈文字颜色
 *  emphasisOuterLabelColor: 高亮数据块扇形外圈文字颜色
 *  emphasisOuterItemColor: 高亮数据块扇形遮罩颜色
 */
type LabelConfig = {
    isLabelPrecent: boolean
    normalLabelColor: string
    emphasisInnerLabelColor: string
    emphasisInnerItemColor: string
    emphasisOuterLabelColor: string
    emphasisOuterItemColor: string
}
function main(page: IPage, portlet: IEChartsPortlet) {
    let config = {
        type: ['ECHARTS_PIE__DONUT', 'ECHARTS_PIE']
    }
    let type = portlet.getType();
    if (config.type.indexOf(type) < 0) return;
    /***********开始配置***********/
    let labelConfig: LabelConfig = {
        //是否设置数据标签为百分比，若不需要，可将该值修改为false，开启则为true
        isLabelPrecent: true,
        normalLabelColor: '#ffffff',
        emphasisInnerLabelColor: '#333333',
        emphasisInnerItemColor: 'rgb(27, 255, 246)',
        emphasisOuterLabelColor: 'rgb(25, 255, 224)',
        emphasisOuterItemColor: 'rgba(25, 255, 224, 0.2)'
    }
    /***********结束配置***********/
    clearInterval(SmartbiXMacro.data[portlet.getId() + "旋转标签-占比比例-选中效果"]);
    SmartbiXMacro.data[portlet.getId() + "旋转标签-占比比例-选中效果"] = setInterval(function () {
        let options = portlet.getChartOptions();
        if (!options || !options.series || !options.series[0] || !options.series[0].data || !options.series[0].data.length) {
            return;
        }
        clearInterval(SmartbiXMacro.data[portlet.getId() + "旋转标签-占比比例-选中效果"]);
        //设置外圈的标签以及旋转
        setOuterSerie(options, labelConfig);
        //增加透明背景
        setBackgroundSerie(options, labelConfig);
        //设置被选中的颜色
        setEmphasis(portlet, labelConfig);
        portlet.setChartOptions(options);
    }, 10);
}

/**
 * 设置外圈的标签以及旋转
 */
function setOuterSerie(options: any, labelConfig: LabelConfig) {
    let serie = options.series[0];
    let outerSerie = {
        type: 'pie',
        radius: ['85%', '100%'],
        hoverAnimation: false,
        itemStyle: {
            color: 'transparent',
            borderColor: 'transparent'
        },
        labelLine: {
            normal: {
                show: false,
                length: 30,
                length2: 55,
            },
        },
        label: {
            color: '',
            normal: {
                position: 'inside',
                align: 'right',
            },
        },
        tooltip: {
            show: false
        },
        name: '',
        data: SmartbiXMacro.utils.deepClone(true, [], serie.data),
    };
    let total = 0;
    for (let i = 0; i < serie.data.length; i++) {
        total += parseFloat(serie.data[i].value[0]);
    }
    for (let i = 0; i < outerSerie.data.length; i++) {
        //设置标签颜色
        serie.data[i].label = serie.data[i].label || {};
        serie.data[i].label.color = labelConfig.normalLabelColor || serie.label.color;
        outerSerie.data[i]['label'] = outerSerie.data[i]['label'] || {};
        outerSerie.data[i]['label'].color = labelConfig.normalLabelColor || serie.label.color;
        // //设置外部、内部标签的旋转角度
        outerSerie.data[i].value[0] = 1;
        outerSerie.data[i]['label']['rotate'] = angleText(i, outerSerie.data.length);
        serie.data[i]['label']['rotate'] = angleText(i, outerSerie.data.length);
        // //设置外部标签的半径
        outerSerie.radius = outerSerie.radius || ['85%', '100%'];
        let radius0 = '85', radius1 = '100';
        if (serie.radius) {
            radius0 = serie.radius[0].substr(0, serie.radius[0].length - 1);
            radius1 = serie.radius[1].substr(0, serie.radius[1].length - 1);
        }
        let radiusSize = Math.max(parseFloat(radius0), parseFloat(radius1));
        outerSerie.radius[0] = radiusSize + '%';
        outerSerie.radius[1] = radiusSize + 15 + '%';
        // //设置外部、内部标签的显示内容
        let before = labelConfig.isLabelPrecent ? '{d}%' : '{c}'
        serie.data[i].label = serie.data[i].label || {};
        serie.data[i].label.formatter = `${before}`
        outerSerie.data[i].label = outerSerie.data[i].label || {};
        outerSerie.data[i].label.formatter = outerSerie.data[i].displayValue[0];
    }
    options.series.push(outerSerie);
}
/**
 *  增加透明背景
 */
function setBackgroundSerie(option: any, labelConfig: LabelConfig) {
    let serie = option.series[1];
    let bgserie = {
        type: 'pie',
        zlevel: 99,
        //透明背景的半径
        radius: ['15%', '90%'],
        selectedOffset: 0,
        animation: false,
        hoverAnimation: false,
        label: {
            normal: {
                show: false,
            },
        },
        data: SmartbiXMacro.utils.deepClone(true, [], serie.data)
    }
    // //设置背景图的默认颜色,初始时下表为0的图呈现选中状态
    for (let i = 0; i < bgserie.data.length; i++) {
        bgserie.data[i].itemStyle = bgserie.data[i].itemStyle || {};
        bgserie.data[i].itemStyle.borderColor = 'transparent';
        if (i == 0) {
            option.series[0].data[0].label = option.series[0].data[0].label || {};
            option.series[0].data[0].label.color = labelConfig.emphasisInnerLabelColor;
            option.series[0].data[0].itemStyle = option.series[0].data[0].itemStyle || {}
            option.series[0].data[0].itemStyle.color = labelConfig.emphasisInnerItemColor;
            option.series[1].data[0].label = option.series[1].data[0].label || {};
            option.series[1].data[0].label.color = labelConfig.emphasisOuterLabelColor;

            bgserie.data[0].itemStyle.color = labelConfig.emphasisOuterItemColor;
        } else {
            bgserie.data[i].itemStyle.color = 'transparent';
        }
    }
    option.series.push(bgserie);
}
/**
 * 设置被选中的颜色
 */
function setEmphasis(portlet: any, labelConfig: LabelConfig) {
    portlet.addChartsListener('click', function (e: any) {
        let option = portlet.getChartOptions();
        //最外层的字体颜色重置变色
        for (var da1 = 0; da1 < option.series[1].data.length; da1++) {
            option.series[1].data[da1].label = option.series[1].data[da1].label || {};
            option.series[1].data[da1].label.color = labelConfig.normalLabelColor || option.series[0].label.color;
            option.series[1].data[da1].itemStyle = option.series[1].data[da1].itemStyle || {};
        }
        //色圈的字体颜色和选中颜色重置
        for (var da2 = 0; da2 < option.series[0].data.length; da2++) {
            option.series[0].data[da2].itemStyle = option.series[0].data[da2].itemStyle || {};
            delete option.series[0].data[da2].itemStyle
            option.series[0].data[da2].label = option.series[0].data[da2].label || {};
            delete option.series[0].data[da2].label.color
        }
        // //背景的透明饼图的重置
        for (var da3 = 0; da3 < option.series[2].data.length; da3++) {
            option.series[2].data[da3].itemStyle = option.series[2].data[da3].itemStyle || {};
            option.series[2].data[da3].itemStyle.color = 'transparent';
        }
        //hover 颜色改变
        option.series[0].data[e.dataIndex].label = option.series[0].data[e.dataIndex].label || {};
        option.series[0].data[e.dataIndex].label.color = labelConfig.emphasisInnerLabelColor;
        option.series[0].data[e.dataIndex].itemStyle = option.series[0].data[e.dataIndex].itemStyle || {}
        option.series[0].data[e.dataIndex].itemStyle.color = labelConfig.emphasisInnerItemColor
        option.series[1].data[e.dataIndex].label = option.series[1].data[e.dataIndex].label || {};
        option.series[1].data[e.dataIndex].label.color = labelConfig.emphasisOuterLabelColor;
        option.series[2].data[e.dataIndex].itemStyle = option.series[2].data[e.dataIndex].itemStyle || {};
        option.series[2].data[e.dataIndex].itemStyle.color = labelConfig.emphasisOuterItemColor;
        portlet.setChartOptions(option);
    });
}

/**
 * 旋转标签
 */
function angleText(i: any, num: any): number | any {
    //每个元素的角度
    var everyAngle = 360 / num;
    //文字现在所在的角度
    var currentAngle = i * everyAngle + everyAngle / 2;
    //文字所在模块的所占角度
    var currentArea = (i + 1) * everyAngle;
    if (currentAngle <= 90) {
        return -currentAngle;
    } else if (currentAngle <= 180 && currentAngle > 90) {
        return 180 - currentAngle;
    } else if (currentAngle < 270 && currentAngle > 180) {
        return 180 - currentAngle;
    } else if (currentAngle < 360 && currentAngle >= 270) {
        return 360 - currentAngle;
    }
}

module.script:
"use strict";
/******************************宏代码说明******************************
* 类型：ClientSide
* 对象：圆环图
* 事件：onBeforeRender
* 效果描述：内圈圆环-圆环圆角-圆环间距-发光效果-占比比例
* 是否可修改：此宏代码不支持修改
**********************************************************************/
function main(page, portlet) {
    var config = {
        type: ['ECHARTS_PIE__DONUT', 'ECHARTS_PIE']
    };
    var type = portlet.getType();
    if (config.type.indexOf(type) < 0)
        return;
    /***********开始配置***********/
    //内圈圆环配置
    var innerRingConfig = {
        //圆环宽度
        width: 100,
        //圆环高度
        height: 100,
    };
    /***********结束配置***********/
    var name = "内圈圆环-圆环圆角-圆环间距-发光效果-占比比例_" + portlet.getId();
    clearInterval(SmartbiXMacro.data[name]);
    SmartbiXMacro.data[name] = setInterval(function () {
        var options = portlet.getChartOptions();
        if (!options || !options.series || !options.series[0] || !options.series[0].data || !options.series[0].data.length) {
            return;
        }
        clearInterval(SmartbiXMacro.data[name]);
        //把data先设置进图例，因为后面需要修改data插入空数据
        setLegend(portlet);
        //设置内圈圆环
        setInnerRing(portlet, innerRingConfig);
        //设置圆环圆角、圆环间距、发光效果
        setCircularFillet(options);
        portlet.setChartOptions(options);
    }, 10);
}
/**
 * 把data先设置进图例，因为后面需要修改data插入空数据
 */
function setLegend(portlet) {
    var options = portlet.getChartOptions();
    if (options.legend[0]) {
        options.legend[0].data = options.series[0].data;
        portlet.setChartOptions(options);
    }
}
/**
 * 设置内圈圆环
 */
function setInnerRing(portlet, innerRingConfig) {
    var options = portlet.getChartOptions();
    var offsetHeight = portlet.getChartInstance()._dom.getElementsByTagName("canvas")[0].offsetHeight;
    var offsetWidth = portlet.getChartInstance()._dom.getElementsByTagName("canvas")[0].offsetWidth;
    var serie = options.series[0];
    var left, top;
    if (serie.center && serie.center.length == 2) {
        left = parseFloat(serie.center[0].substr(0, serie.center[0].indexOf('%'))) * offsetWidth / 100 - innerRingConfig.width / 2;
        top = parseFloat(serie.center[1].substr(0, serie.center[1].indexOf('%'))) * offsetHeight / 100 - innerRingConfig.height / 2;
        left = left.toFixed(0);
        top = top.toFixed(0);
    }
    else {
        left = 'center';
        top = 'center';
    }
    var img = 'data:image/png;base64,';
    var pic = {
        type: 'image',
        z: 3,
        style: {
            image: img,
            width: innerRingConfig.width,
            height: innerRingConfig.height,
        },
        left: left,
        top: top,
    };
    options.graphic = options.graphic || {};
    options.graphic.elements = options.graphic.elements || [];
    options.graphic.elements.push(pic);
    portlet.setChartOptions(options);
}
/**
 * 设置圆环圆角、圆环间距、发光效果
 */
function setCircularFillet(options) {
    var serie = options.series[0];
    var data = serie.data;
    var newData = [];
    var total = 0;
    for (var i = 0; i < data.length; i++) {
        total += data[i].value[0];
    }
    serie.label = serie.label || {};
    for (var i = 0; i < data.length; i++) {
        data[i].itemStyle = data[i].itemStyle || {};
        //圆环圆角
        data[i].itemStyle.borderWidth = 5;
        data[i].itemStyle.borderRadius = 50;
        data[i].itemStyle.borderColor = 'transparent';
        //发光效果
        data[i].itemStyle.shadowColor = options.color[i % 10];
        data[i].itemStyle.shadowBlur = 5;
        //圆环间距
        var gapData = {
            value: [total * 0.01],
            name: '',
            labelLine: {
                show: false,
            },
            itemStyle: {
                normal: {
                    label: {
                        show: false,
                    },
                    color: 'rgba(0, 0, 0, 0)',
                    borderColor: 'rgba(0, 0, 0, 0)',
                    borderWidth: 0,
                },
            },
            tooltip: {
                show: false
            }
        };
        newData.push(data[i], gapData);
    }
    serie.data = newData;
}

