        let gapData = {
            value: [total * 0.01],
            name: '',
            labelLine: {
                show: false,
            },
            itemStyle: {
                normal: {
                    label: {
                        show: false,
                    },
                    color: 'rgba(0, 0, 0, 0)',
                    borderColor: 'rgba(0, 0, 0, 0)',
                    borderWidth: 0,
                },
            },
            tooltip: {
                show: false
            }
        }
        newData.push(data[i], gapData);
    }
    serie.data = newData;
}

module.script:
"use strict";
/******************************宏代码说明******************************
* 类型：ClientSide
* 对象：圆环图
* 事件：onBeforeRender
* 效果描述：内圈圆环-圆环圆角-圆环间距-发光效果-占比比例
* 是否可修改：此宏代码不支持修改
**********************************************************************/
function main(page, portlet) {
    var config = {
        type: ['ECHARTS_PIE__DONUT', 'ECHARTS_PIE']
    };
    var type = portlet.getType();
    if (config.type.indexOf(type) < 0)
        return;
    /***********开始配置***********/
    //内圈圆环配置
    var innerRingConfig = {
        //圆环宽度
        width: 100,
        //圆环高度
        height: 100,
    };
    /***********结束配置***********/
    var name = "内圈圆环-圆环圆角-圆环间距-发光效果-占比比例_" + portlet.getId();
    clearInterval(SmartbiXMacro.data[name]);
    SmartbiXMacro.data[name] = setInterval(function () {
        var options = portlet.getChartOptions();
        if (!options || !options.series || !options.series[0] || !options.series[0].data || !options.series[0].data.length) {
            return;
        }
        clearInterval(SmartbiXMacro.data[name]);
        //把data先设置进图例，因为后面需要修改data插入空数据
        setLegend(portlet);
        //设置内圈圆环
        setInnerRing(portlet, innerRingConfig);
        //设置圆环圆角、圆环间距、发光效果
        setCircularFillet(options);
        portlet.setChartOptions(options);
    }, 10);
}
/**
 * 把data先设置进图例，因为后面需要修改data插入空数据
 */
function setLegend(portlet) {
    var options = portlet.getChartOptions();
    if (options.legend[0]) {
        options.legend[0].data = options.series[0].data;
        portlet.setChartOptions(options);
    }
}
/**
 * 设置内圈圆环
 */
function setInnerRing(portlet, innerRingConfig) {
    var options = portlet.getChartOptions();
    var offsetHeight = portlet.getChartInstance()._dom.getElementsByTagName("canvas")[0].offsetHeight;
    var offsetWidth = portlet.getChartInstance()._dom.getElementsByTagName("canvas")[0].offsetWidth;
    var serie = options.series[0];
    var left, top;
    if (serie.center && serie.center.length == 2) {
        left = parseFloat(serie.center[0].substr(0, serie.center[0].indexOf('%'))) * offsetWidth / 100 - innerRingConfig.width / 2;
        top = parseFloat(serie.center[1].substr(0, serie.center[1].indexOf('%'))) * offsetHeight / 100 - innerRingConfig.height / 2;
        left = left.toFixed(0);
        top = top.toFixed(0);
    }
    else {
        left = 'center';
        top = 'center';
    }
    var img = 'data:image/png;base64,';
    var pic = {
        type: 'image',
        z: 3,
        style: {
            image: img,
            width: innerRingConfig.width,
            height: innerRingConfig.height,
        },
        left: left,
        top: top,
    };
    options.graphic = options.graphic || {};
    options.graphic.elements = options.graphic.elements || [];
    options.graphic.elements.push(pic);
    portlet.setChartOptions(options);
}
/**
 * 设置圆环圆角、圆环间距、发光效果
 */
function setCircularFillet(options) {
    var serie = options.series[0];
    var data = serie.data;
    var newData = [];
    var total = 0;
    for (var i = 0; i < data.length; i++) {
        total += data[i].value[0];
    }
    serie.label = serie.label || {};
    for (var i = 0; i < data.length; i++) {
        data[i].itemStyle = data[i].itemStyle || {};
        //圆环圆角
        data[i].itemStyle.borderWidth = 5;
        data[i].itemStyle.borderRadius = 50;
        data[i].itemStyle.borderColor = 'transparent';
        //发光效果
        data[i].itemStyle.shadowColor = options.color[i % 10];
        data[i].itemStyle.shadowBlur = 5;
        //圆环间距
        var gapData = {
            value: [total * 0.01],
            name: '',
            labelLine: {
                show: false,
            },
            itemStyle: {
                normal: {
                    label: {
                        show: false,
                    },
                    color: 'rgba(0, 0, 0, 0)',
                    borderColor: 'rgba(0, 0, 0, 0)',
                    borderWidth: 0,
                },
            },
            tooltip: {
                show: false
            }
        };
        newData.push(data[i], gapData);
    }
    serie.data = newData;
}

