    clearInterval(SmartbiXMacro.data[name]);
    SmartbiXMacro.data[name] = setInterval(function () {
        var options = portlet.getChartOptions();
        if (!options || !options.series || !options.series[0] || !options.series[0].data || !options.series[0].data.length) {
            return;
        }
        clearInterval(SmartbiXMacro.data[name]);
        //把data先设置进图例，因为后面需要修改data插入空数据
