        setCircularFillet(options);
        //设置填充饼图的图层
        setInnerPieSerie(options);
        portlet.setChartOptions(options);
    }, 10);
}
/**
 * 把data先设置进图例，因为后面需要修改data插入空数据
 */
function setLegend(portlet) {
    var options = portlet.getChartOptions();
    if (options.legend[0]) {
        options.legend[0].data = options.series[0].data;
        portlet.setChartOptions(options);
    }
}
/**
 * 设置填充饼图的图层
 */
function setInnerPieSerie(options) {
    var serie = options.series[0];
    var maxSerie = Math.min(parseFloat(serie.radius[1].substr(0, serie.radius[1].length - 1)), parseFloat(serie.radius[0].substr(0, serie.radius[1].length - 1))) - 10 + '%';
    var innerPieSerie = {
        name: '',
        type: 'pie',
        radius: ['0%', maxSerie],
        data: [1],
        tooltip: {
            show: false
        },
        label: {
            show: false
        },
        itemStyle: {
            //内置饼图的颜色
            color: 'rgba(32,134,253, 0.5)',
            // 设置内置饼图边框宽度为0
            borderWidth: 0
        }
    };
    options.series.push(innerPieSerie);
}
/**
 * 设置圆环间距
 */
function setCircularFillet(options) {
    var serie = options.series[0];
    var data = serie.data;
    var newData = [];
    var total = 0;
    for (var i = 0; i < data.length; i++) {
        total += data[i].value[0];
    }
    serie.label = serie.label || {};
    for (var i = 0; i < data.length; i++) {
        //圆环间距
        var gapData = {
            value: [total * 0.01],
            name: '',
            labelLine: {
                show: false,
            },
            itemStyle: {
                normal: {
                    label: {
                        show: false,
                    },
                    color: 'rgba(0, 0, 0, 0)',
                    borderColor: 'rgba(0, 0, 0, 0)',
                    borderWidth: 0,
                },
            },
            tooltip: {
                show: false
            }
        };
        newData.push(data[i], gapData);
    }
    serie.data = newData;
}

