module.script:
"use strict";
/******************************宏代码说明******************************
 * 类型：ClientSide
 * 对象：涟漪散点和区域组合地图
 * 事件：onBeforeRender
 * 效果描述：形成3D效果
 *********************************************************************/
function main(page, portlet) {
    var config = {
        type: ['ECHARTS_MAP']
    };
    var type = portlet.getType();
    if (config.type.indexOf(type) < 0)
        return;
    var options = portlet.getChartOptions();
    var geo;
    if (options.geo instanceof Array) {
        geo = options.geo[0];
    }
    else {
        geo = options.geo;
        options.geo = [];
    }
    geo.zlevel = 0; //设置优先级
    options.geo.push(geo);
    //地图图层偏移形成3D效果
    /**********************开始配置*********************/
    var deviationItemStyle = {
        areaColor: '#013C62',
        shadowColor: '#1d4057',
        shadowOffsetX: -1,
        shadowOffsetY: 15,
    };
    /**********************结束配置*********************/
    var geoShadow = getGeoItemStyle(-2, deviationItemStyle, options.geo[0]);
    options.geo.push(geoShadow);
}
/*
 * 获取geo的样式
 */
function getGeoItemStyle(zlevel, geoItemStyle, geo) {
    console.log(99999);
    return {
        type: 'map',
        map: geo.map,
        zoom: geo.zoom,
        zlevel: zlevel,
        roam: false,
        tooltip: {
            show: false
        },
        label: {
            normal: {
                show: false,
            },
        },
        itemStyle: geoItemStyle,
        regions: hideRegions()
    };
}
//返回隐藏右下角地图的信息
function hideRegions() {
    var regions = [
        {
            name: "南海诸岛",
            itemStyle: {
                // 隐藏地图
                normal: {
                    opacity: 0,
                }
            },
            label: {
                show: false // 隐藏文字
            }
        }
    ];
    return regions;
}

module.typescript:
/******************************宏代码说明******************************
 * 类型：ClientSide
 * 对象：涟漪散点和区域组合地图
 * 事件：onBeforeRender
 * 效果描述：形成3D效果
 *********************************************************************/

/**
* 设置项
*  areaColor: 区域颜色
*  shadowColor:发光颜色
*  shadowOffsetX:较原位置的x轴偏移
*  shadowOffsetY:较原位置的y轴偏移
*/
type DeviationItemStyle = {
    areaColor: string,
    shadowColor: string,
    shadowOffsetX: number,
    shadowOffsetY: number,
}
function main(page: IPage, portlet: IEChartsPortlet) {
    let config = {
        type: ['ECHARTS_MAP']
    }
    let type = portlet.getType();
    if (config.type.indexOf(type) < 0) return;

    let options = portlet.getChartOptions();
    let geo;
    if (options.geo instanceof Array) {
        geo = options.geo[0];
    } else {
        geo = options.geo;
        options.geo = [];
    }
    geo.zlevel = 0;//设置优先级
    options.geo.push(geo);

    //地图图层偏移形成3D效果
    /**********************开始配置*********************/
    let deviationItemStyle: DeviationItemStyle = {
        areaColor: '#013C62',           
        shadowColor: '#1d4057',
        shadowOffsetX: -1,
        shadowOffsetY: 15,
    }
    /**********************结束配置*********************/
    let geoShadow = getGeoItemStyle(-2, deviationItemStyle, options.geo[0]);
    options.geo.push(geoShadow);
}

/*
 * 获取geo的样式
 */
function getGeoItemStyle(zlevel: number, geoItemStyle: any, geo: any) {
    console.log(99999)
    return {
        type: 'map',
        map: geo.map,
        zoom: geo.zoom,
        zlevel: zlevel,//图层显示顺序，数值大的会覆盖在小的上面
        roam: false,
        tooltip: {
            show: false
        },
        label: {//区域标签设置
            normal: {
                show: false,//若想地图上显示区域名称，设置为true
            },
        },
        itemStyle: geoItemStyle,
        regions: hideRegions()
    }
}

//返回隐藏右下角地图的信息
function hideRegions() {
    let regions = [
        {
            name: "南海诸岛",
            itemStyle: {
                // 隐藏地图
                normal: {
                    opacity: 0, // 为 0 时不绘制该图形
                }
            },
            label: {
                show: false // 隐藏文字
            }
        }
    ]
    return regions;
}
